import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { build } from 'vite';

const frontendRoot = fileURLToPath(new URL('../', import.meta.url));
const configFile = fileURLToPath(new URL('../vite.activity-player.config.ts', import.meta.url));
const outputFile = fileURLToPath(new URL('../src/features/teaching-studio/components/activityPlayerBundle.generated.ts', import.meta.url));
const result = await build({ configFile, root: frontendRoot });
const outputs = (Array.isArray(result) ? result : [result]).flatMap((buildResult) => buildResult.output);
const script = outputs.find((output) => output.type === 'chunk' && output.isEntry);
const stylesheet = outputs.find((output) => output.type === 'asset' && output.fileName.endsWith('.css'));

if (!script || script.type !== 'chunk' || !stylesheet || stylesheet.type !== 'asset') {
  throw new Error('Vite did not produce the Activity Player JavaScript and CSS bundles.');
}

const css = typeof stylesheet.source === 'string'
  ? stylesheet.source
  : new TextDecoder().decode(stylesheet.source);
const source = `// Generated by scripts/generate-activity-player-bundle.mjs. Do not edit manually.\n`
  + `export const ACTIVITY_PLAYER_SCRIPT = ${JSON.stringify(script.code)};\n`
  + `export const ACTIVITY_PLAYER_STYLES = ${JSON.stringify(css)};\n`;

await writeFile(outputFile, source, 'utf8');
console.log(`Generated the standalone Activity Player (${script.code.length} bytes JS, ${css.length} bytes CSS).`);
